using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns the high scores for a game and some part of the high score table in the range of the specified user; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.GameHighScores> GetGameHighScoresAsync(long chatId = default, long messageId = default, long userId = default)
    {

           using var activity =  StartCallActivity("GetGameHighScoresAsync", typeof(GetGameHighScores).FullName ?? "GetGameHighScoresAsync");

           try
           {
             return client.GetGameHighScoresAsync(chatId, messageId, userId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
